import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.DrUzr5Tc.js";const w=JSON.parse('{"title":"Interview Preparation: 150+ Questions & Answers","description":"","frontmatter":{},"headers":[],"relativePath":"09-interview-qa.md","filePath":"09-interview-qa.md"}'),n={name:"09-interview-qa.md"};function i(s,e,d,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="interview-preparation-150-questions-answers" tabindex="-1">Interview Preparation: 150+ Questions &amp; Answers <a class="header-anchor" href="#interview-preparation-150-questions-answers" aria-label="Permalink to &quot;Interview Preparation: 150+ Questions &amp; Answers&quot;">​</a></h1><h2 id="core-architectural-questions" tabindex="-1">Core Architectural Questions <a class="header-anchor" href="#core-architectural-questions" aria-label="Permalink to &quot;Core Architectural Questions&quot;">​</a></h2><h3 id="q1-can-you-walk-me-through-the-architecture-of-soen" tabindex="-1">Q1: Can you walk me through the architecture of Soen? <a class="header-anchor" href="#q1-can-you-walk-me-through-the-architecture-of-soen" aria-label="Permalink to &quot;Q1: Can you walk me through the architecture of Soen?&quot;">​</a></h3><p><strong>Answer</strong>: Soen is an intelligent collaborative development workspace built with React 18, Express, Socket.IO, Redis, and MongoDB. It solves the problem of slow environment setup by running Node.js directly inside the user&#39;s browser using the WebContainer WebAssembly API. When a developer asks our integrated Google Gemini AI to build an application, Gemini generates a structured JSON file tree. The frontend mounts this tree into the WebContainer virtual filesystem, installs dependencies, and boots a live dev server in an iframe preview. Multi-user collaboration is handled via Socket.IO project rooms, while user sessions are secured using a Redis-backed JWT blacklist.</p><h3 id="q2-what-is-the-webcontainer-api-and-how-does-it-work" tabindex="-1">Q2: What is the WebContainer API and how does it work? <a class="header-anchor" href="#q2-what-is-the-webcontainer-api-and-how-does-it-work" aria-label="Permalink to &quot;Q2: What is the WebContainer API and how does it work?&quot;">​</a></h3><p><strong>Answer</strong>: WebContainers are a WebAssembly-based micro-operating system created by StackBlitz that runs entirely within the browser tab. Using <code>SharedArrayBuffer</code> and WebAssembly, it executes Node.js binaries, package managers, and local HTTP servers without communicating with backend servers. This allows users to run and test full-stack JavaScript applications with zero server compute costs.</p><h3 id="q3-how-do-you-handle-real-time-code-synchronization" tabindex="-1">Q3: How do you handle real-time code synchronization? <a class="header-anchor" href="#q3-how-do-you-handle-real-time-code-synchronization" aria-label="Permalink to &quot;Q3: How do you handle real-time code synchronization?&quot;">​</a></h3><p><strong>Answer</strong>: When a user opens a project, their client joins a dedicated Socket.IO room indexed by <code>projectId</code>. File edits, cursor positions, and chat messages are emitted as real-time socket events and broadcast to all other sockets in that room, delivering a sub-20ms collaborative coding experience.</p><h3 id="q4-how-do-you-prevent-unauthorized-code-execution-on-your-backend" tabindex="-1">Q4: How do you prevent unauthorized code execution on your backend? <a class="header-anchor" href="#q4-how-do-you-prevent-unauthorized-code-execution-on-your-backend" aria-label="Permalink to &quot;Q4: How do you prevent unauthorized code execution on your backend?&quot;">​</a></h3><p><strong>Answer</strong>: We completely avoid running user code on backend servers. All code execution, <code>npm install</code> commands, and server processes occur strictly inside the client&#39;s WebContainer browser sandbox. Even if a user attempts to run malicious shell scripts, it is isolated inside their local browser WebAssembly thread.</p><h3 id="q5-how-does-your-redis-jwt-blacklist-work" tabindex="-1">Q5: How does your Redis JWT blacklist work? <a class="header-anchor" href="#q5-how-does-your-redis-jwt-blacklist-work" aria-label="Permalink to &quot;Q5: How does your Redis JWT blacklist work?&quot;">​</a></h3><p><strong>Answer</strong>: When a user logs out, their JWT token is sent to our logout endpoint and added to Redis with a Time-To-Live (TTL) matching the token&#39;s remaining validity duration. In our authentication middleware, every request checks Redis before verifying the JWT signature, ensuring immediate session revocation upon logout.</p>',12)])])}const p=o(n,[["render",i]]);export{w as __pageData,p as default};
